{
  "@context": "https://schema.org",
  "@type": "FAQPage",
  "mainEntity": [
    {
      "@type": "Question",
      "name": "What is considered a whole home renovation?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "A whole home renovation typically involves remodeling multiple areas of the home as part of one cohesive project. This may include kitchens, bathrooms, living spaces, flooring, trim work, layout changes, structural modifications, and overall design updates intended to improve how the home functions and feels as a whole."
      }
    },
    {
      "@type": "Question",
      "name": "Can you help redesign the layout of our home?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Yes. Many whole home renovations involve reworking outdated floor plans to create better flow, improved functionality, and more connected living spaces. We frequently remove walls, install structural beams, redesign kitchens, reconfigure rooms, and create layouts that better support modern living."
      }
    },
    {
      "@type": "Question",
      "name": "Do you work on older homes in Columbus?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Absolutely. Many homes throughout Upper Arlington, Bexley, Worthington, and surrounding Columbus neighborhoods require thoughtful planning to preserve character while improving functionality and updating finishes. We regularly work within existing home structures while modernizing layouts and living spaces."
      }
    },
    {
      "@type": "Question",
      "name": "Can you renovate multiple rooms at the same time?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Yes. Whole home renovations are designed to coordinate multiple spaces as part of a unified plan. Managing the project comprehensively often creates a more cohesive final result and can help streamline the overall construction process."
      }
    },
    {
      "@type": "Question",
      "name": "Can you make structural changes as part of a renovation?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Yes. We regularly remove or relocate walls, install structural beams, and reconfigure layouts within your home's existing footprint. We don't build additions. Our work focuses on reimagining the space you already have."
      }
    },
    {
      "@type": "Question",
      "name": "Can we live in the home during a whole home renovation?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "That depends on the scope of work and which areas of the home are being renovated. Some homeowners remain in the home during portions of construction, while others choose temporary accommodations depending on the scale of the project."
      }
    },
    {
      "@type": "Question",
      "name": "Do you handle permits and project coordination?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Yes. We coordinate the various aspects of the renovation process including planning, scheduling, permitting, inspections, and construction management to help keep projects organized and moving efficiently."
      }
    },
    {
      "@type": "Question",
      "name": "What areas around Columbus do you serve?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "We provide whole home remodeling throughout Columbus and surrounding communities including Upper Arlington, Grandview Heights, Dublin, Worthington, Bexley, Powell, Clintonville, Lewis Center, Westerville and more. If you're not sure whether we work in your area, reach out and ask."
      }
    }
  ]
}

